WITH metrics_long AS (SELECT * FROM (SELECT id, store_id, discount, amount, shipping_fee FROM orders) src UNPIVOT (value FOR kpi IN (discount, amount, shipping_fee)) unp) SELECT CASE WHEN value >= 85 THEN 'LARGE' ELSE 'SMALL' END AS value_tier, PERCENTILE_APPROX(value, ARRAY(0.25, 0.5, 0.75)) AS value_quartiles, PERCENTILE_APPROX(value, 0.95) AS value_p95, COUNT_IF(kpi = 'shipping_fee') AS shipping_fee_events, COUNT_IF(kpi = 'discount') AS discount_events FROM metrics_long GROUP BY CASE WHEN value >= 85 THEN 'LARGE' ELSE 'SMALL' END ORDER BY value_tier DESC NULLS LAST
